targets.rawSql:
SELECT code AS "Mã",scope AS "Tài trợ",kind AS "Loại",redemptions AS "Đã dùng",usage_limit AS "Giới hạn",
       redemption_rate AS "Dùng / quota",discount_cost AS "Ưu đãi"
FROM mart.voucher_performance WHERE refresh_id = ${refresh_id:raw} AND scope IN (${voucher_scope:sqlstring}) ORDER BY discount_cost DESC LIMIT ${top_n:raw}

SELECT concat(substringUTF8(campaign,1,38),' · ',formatDateTime(starts_at,'%d/%m','Asia/Ho_Chi_Minh')) AS "Chiến dịch",
       sell_through AS "Đã bán / quota"
FROM mart.flash_sale_performance WHERE refresh_id = ${refresh_id:raw}
  AND starts_at <= (SELECT max(hour) FROM mart.traffic_by_hour WHERE refresh_id = ${refresh_id:raw})
ORDER BY starts_at DESC LIMIT ${top_n:raw}
